import math

def norm_map(vals):
    minr=min(r for r,c in vals); minc=min(c for r,c in vals)
    return {(r-minr,c-minc):v for (r,c),v in vals.items()}

def dihedral_maps(vals):
    pts=list(vals)
    out=[]
    for refl in range(2):
        for rot in range(4):
            transformed={}
            for (r,c),v in vals.items():
                if refl: c=-c
                for _ in range(rot): r,c=c,-r
                transformed[(r,c)]=v
            nm=norm_map(transformed)
            key=tuple(sorted(nm.items()))
            if all(key != x[0] for x in out): out.append((key,nm))
    return [m for _,m in out]

def make_placements(values_by_piece, n):
    pids=list(values_by_piece)
    byp={p:[] for p in pids}
    bycell={p:[[] for _ in range(n*n)] for p in pids}
    for p, vals in values_by_piece.items():
        orientations=dihedral_maps(vals)
        for oi, om in enumerate(orientations):
            h=max(r for r,c in om)+1; w=max(c for r,c in om)+1
            if h>n or w>n: continue
            for dr in range(n-h+1):
                for dc in range(n-w+1):
                    cells=tuple(sorted((r+dr,c+dc,v) for (r,c),v in om.items()))
                    mask=0
                    for r,c,v in cells: mask |= 1 << (r*n+c)
                    pl={'p':p,'oi':oi,'dr':dr,'dc':dc,'cells':cells,'mask':mask}
                    byp[p].append(pl)
                    for r,c,v in cells: bycell[p][r*n+c].append(pl)
    return byp,bycell

def empty_components(n, occupied):
    empty= ((1<<(n*n))-1) ^ occupied
    comps=[]
    unseen=empty
    while unseen:
        bit=unseen & -unseen
        i=bit.bit_length()-1
        stack=[i]; unseen ^= bit; count=0
        while stack:
            j=stack.pop(); count += 1
            r,c=divmod(j,n)
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0<=nr<n and 0<=nc<n:
                    b=1<<(nr*n+nc)
                    if unseen & b:
                        unseen ^= b; stack.append(nr*n+nc)
        comps.append(count)
    return comps

def component_area_prune(n, occupied, remaining, sizes):
    comps=empty_components(n,occupied)
    if len(comps)>len(remaining): return False
    # every component must receive a disjoint subset of piece areas, and all pieces are assigned
    # enumerate assigning remaining pieces to component bins; pieces connected
    bins=[0]*len(comps)
    rem_sizes=[sizes[p] for p in remaining]
    def rec(i):
        if i==len(rem_sizes): return all(bins[j]==comps[j] for j in range(len(comps)))
        a=rem_sizes[i]
        seen=set()
        for j, cap in enumerate(comps):
            if bins[j] in seen: continue
            seen.add(bins[j])
            if bins[j]+a<=cap:
                bins[j]+=a
                if rec(i+1): return True
                bins[j]-=a
        return False
    return rec(0)

def solve_tiling(values_by_piece,n, maxnodes=1000000, maxsol=1):
    byp, bycell=make_placements(values_by_piece,n)
    sizes={p:len(v) for p,v in values_by_piece.items()}
    full=(1<<(n*n))-1
    sols=[]; nodes=0
    def dfs(occ, rem, chosen):
        nonlocal nodes
        nodes+=1
        if nodes>maxnodes: return True
        if not rem:
            if occ==full:
                sols.append(chosen.copy())
                return len(sols)>=maxsol
            return False
        # Find most constrained uncovered cell. Also fail if no placement covers it.
        best=None; bestc=None
        unocc = full ^ occ
        while unocc:
            b=unocc & -unocc; idx=b.bit_length()-1; unocc ^= b
            cand=[]
            for p in rem:
                for pl in bycell[p][idx]:
                    if pl['mask'] & occ == 0:
                        cand.append(pl)
            if not cand: return False
            if best is None or len(cand)<len(best):
                best=cand; bestc=idx
                if len(best)==1: break
        # branch based on candidates; order pieces by area maybe larger
        best.sort(key=lambda pl:(-sizes[pl['p']],pl['p'],pl['oi'],pl['dr'],pl['dc']))
        for pl in best:
            p=pl['p']
            nrem=tuple(q for q in rem if q!=p)
            no=occ|pl['mask']
            if component_area_prune(n,no,nrem,sizes):
                chosen[p]=pl
                stop=dfs(no,nrem,chosen)
                chosen.pop(p,None)
                if stop: return True
        return False
    # Avoid the repetitive component prune at root and enumerate.
    dfs(0,tuple(values_by_piece),{})
    return sols,nodes,{p:len(v) for p,v in byp.items()}

